function permuteUnique(nums) {
  const seen = new Set();
  const result = [];
  const used = new Array(nums.length).fill(false);
  const path = [];
  const build = () => {
    if (path.length === nums.length) {
      const key = path.join(",");
      if (!seen.has(key)) {                // keep only the first copy of each
        seen.add(key);
        result.push([...path]);
      }
      return;
    }
    for (let i = 0; i < nums.length; i++) {
      if (used[i]) continue;
      used[i] = true;
      path.push(nums[i]);
      build();
      path.pop();
      used[i] = false;
    }
  };
  build();
  return result;
}

