void build(int[] nums, boolean[] used, List<Integer> path, Set<List<Integer>> seen) {
    if (path.size() == nums.length) {
        seen.add(new ArrayList<>(path));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) continue;
        used[i] = true;
        path.add(nums[i]);
        build(nums, used, path, seen);
        path.remove(path.size() - 1);
        used[i] = false;
    }
}

