function permuteUnique(nums) {
  const a = [...nums].sort((x, y) => x - y);   // equal values next to each other
  const result = [];
  const path = [];
  const used = new Array(a.length).fill(false);
  const build = () => {
    if (path.length === a.length) {
      result.push([...path]);
      return;
    }
    for (let i = 0; i < a.length; i++) {
      if (used[i]) continue;
      if (i > 0 && a[i] === a[i - 1] && !used[i - 1]) continue;   // equal values go in order
      used[i] = true;
      path.push(a[i]);
      build();
      path.pop();
      used[i] = false;
    }
  };
  build();
  return result;
}

def permute_unique(nums):
    a = sorted(nums)                      # equal values next to each other
    result, path = [], []
    used = [False] * len(a)

    def build():
        if len(path) == len(a):
            result.append(path[:])
            return
        for i in range(len(a)):
            if used[i]:
                continue
            if i > 0 and a[i] == a[i - 1] and not used[i - 1]:
                continue                  # equal values go in order
            used[i] = True
            path.append(a[i])
            build()
            path.pop()
            used[i] = False

    build()
    return result

